1	// JSON Pointer (RFC 6901) and JSON Patch (RFC 6902).
2	
3	export class PatchError extends Error {
4	  constructor(message, index) {
5	    super(message);
6	    this.name = 'PatchError';
7	    this.index = index;
8	  }
9	}
10	
11	const OPS = new Set(['add', 'remove', 'replace', 'move', 'copy', 'test']);
12	const INDEX_RE = /^(?:0|[1-9][0-9]*)$/;
13	
14	export function parsePointer(pointer) {
15	  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
16	  if (pointer === '') return [];
17	  if (pointer[0] !== '/' || /~(?![01])/.test(pointer)) throw new SyntaxError('invalid pointer');
18	  return pointer
19	    .slice(1)
20	    .split('/')
21	    .map((t) => t.replace(/~1/g, '/').replace(/~0/g, '~'));
22	}
23	
24	function isObject(v) {
25	  return v !== null && typeof v === 'object' && !Array.isArray(v);
26	}
27	
28	// Defines an own data property, so names like "__proto__" stay ordinary members.
29	function setMember(obj, name, value) {
30	  Object.defineProperty(obj, name, { value, writable: true, enumerable: true, configurable: true });
31	}
32	
33	function deepCopy(v) {
34	  if (Array.isArray(v)) return v.map(deepCopy);
35	  if (isObject(v)) {
36	    const out = {};
37	    for (const k of Object.keys(v)) setMember(out, k, deepCopy(v[k]));
38	    return out;
39	  }
40	  return v;
41	}
42	
43	function deepEqual(a, b) {
44	  if (Array.isArray(a)) {
45	    if (!Array.isArray(b) || a.length !== b.length) return false;
46	    return a.every((x, i) => deepEqual(x, b[i]));
47	  }
48	  if (isObject(a)) {
49	    if (!isObject(b)) return false;
50	    const ka = Object.keys(a);
51	    if (ka.length !== Object.keys(b).length) return false;
52	    return ka.every((k) => Object.hasOwn(b, k) && deepEqual(a[k], b[k]));
53	  }
54	  return a === b;
55	}
56	
57	// Returns the error reason for an operation that breaks the form rules, or null.
58	function checkForm(op) {
59	  if (op === null || typeof op !== 'object' || Array.isArray(op)) return 'not an object';
60	  const name = Object.hasOwn(op, 'op') ? op.op : undefined;
61	  if (typeof name !== 'string' || !OPS.has(name)) return 'bad op';
62	  const path = validPointer(op, 'path');
63	  if (!path) return 'bad path';
64	  let from = null;
65	  if (name === 'move' || name === 'copy') {
66	    from = validPointer(op, 'from');
67	    if (!from) return 'bad from';
68	  }
69	  if ((name === 'add' || name === 'replace' || name === 'test') && !Object.hasOwn(op, 'value')) {
70	    return 'missing value';
71	  }
72	  if (name === 'remove' && path.length === 0) return 'cannot remove root';
73	  if (name === 'move' && from.length < path.length && from.every((t, i) => t === path[i])) {
74	    return 'cannot move into own child';
75	  }
76	  return null;
77	}
78	
79	function validPointer(op, member) {
80	  if (!Object.hasOwn(op, member) || typeof op[member] !== 'string') return null;
81	  try {
82	    return parsePointer(op[member]);
83	  } catch {
84	    return null;
85	  }
86	}
87	
88	// An operation that fails while applying; its message is the reason.
89	class OperationFailure extends Error {}
90	
91	// Follows tokens from root; returns the value they name or throws an OperationFailure.
92	function resolve(root, tokens, notFound) {
93	  let cur = root;
94	  for (const t of tokens) {
95	    if (Array.isArray(cur)) {
96	      if (t === '-') throw new OperationFailure(notFound);
97	      if (!INDEX_RE.test(t)) throw new OperationFailure('bad index');
98	      if (Number(t) >= cur.length) throw new OperationFailure(notFound);
99	      cur = cur[Number(t)];
100	    } else if (isObject(cur) && Object.hasOwn(cur, t)) {
101	      cur = cur[t];
102	    } else {
103	      throw new OperationFailure(notFound);
104	    }
105	  }
106	  return cur;
107	}
108	
109	// Follows all tokens of a non-empty path but the last; returns the parent and the last token.
110	function resolveParent(doc, path) {
111	  return [resolve(doc, path.slice(0, -1), 'path not found'), path[path.length - 1]];
112	}
113	
114	function addAt(doc, path, value) {
115	  if (path.length === 0) return value;
116	  const [parent, last] = resolveParent(doc, path);
117	  if (Array.isArray(parent)) {
118	    if (last === '-') {
119	      parent.push(value);
120	    } else if (!INDEX_RE.test(last)) {
121	      throw new OperationFailure('bad index');
122	    } else if (Number(last) > parent.length) {
123	      throw new OperationFailure('path not found');
124	    } else {
125	      parent.splice(Number(last), 0, value);
126	    }
127	  } else if (isObject(parent)) {
128	    setMember(parent, last, value);
129	  } else {
130	    throw new OperationFailure('path not found');
131	  }
132	  return doc;
133	}
134	
135	// Removes the value at a non-empty path that is known to exist.
136	function removeAt(doc, path) {
137	  const [parent, last] = resolveParent(doc, path);
138	  if (Array.isArray(parent)) parent.splice(Number(last), 1);
139	  else delete parent[last];
140	}
141	
142	// Replaces the value at a non-empty path that is known to exist, keeping its place.
143	function replaceAt(doc, path, value) {
144	  const [parent, last] = resolveParent(doc, path);
145	  if (Array.isArray(parent)) parent[Number(last)] = value;
146	  else setMember(parent, last, value);
147	  return doc;
148	}
149	
150	function applyOne(doc, op) {
151	  const path = parsePointer(op.path);
152	  switch (op.op) {
153	    case 'add':
154	      return addAt(doc, path, deepCopy(op.value));
155	    case 'remove':
156	      resolve(doc, path, 'path not found');
157	      removeAt(doc, path);
158	      return doc;
159	    case 'replace':
160	      if (path.length === 0) return deepCopy(op.value);
161	      resolve(doc, path, 'path not found');
162	      return replaceAt(doc, path, deepCopy(op.value));
163	    case 'move': {
164	      const from = parsePointer(op.from);
165	      const value = resolve(doc, from, 'from not found');
166	      if (op.from === op.path) return doc;
167	      // The form rules guarantee from is non-empty here (a "" from is a prefix of any other path).
168	      removeAt(doc, from);
169	      return addAt(doc, path, value);
170	    }
171	    case 'copy': {
172	      const value = deepCopy(resolve(doc, parsePointer(op.from), 'from not found'));
173	      return addAt(doc, path, value);
174	    }
175	    case 'test':
176	      if (!deepEqual(resolve(doc, path, 'path not found'), op.value)) {
177	        throw new OperationFailure('test failed');
178	      }
179	      return doc;
180	  }
181	}
182	
183	export function applyPatch(doc, patch) {
184	  if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
185	  const ops = [];
186	  for (let i = 0; i < patch.length; i++) {
187	    const op = patch[i];
188	    const reason = checkForm(op);
189	    if (reason) throw new PatchError(`operation ${i}: ${reason}`, i);
190	    ops.push(op);
191	  }
192	  let result = deepCopy(doc);
193	  for (let i = 0; i < ops.length; i++) {
194	    try {
195	      result = applyOne(result, ops[i]);
196	    } catch (err) {
197	      if (err instanceof OperationFailure) throw new PatchError(`operation ${i}: ${err.message}`, i);
198	      throw err;
199	    }
200	  }
201	  return result;
202	}
