1	#!/usr/bin/env node
2	// Usage: node jsonpatch-cli.mjs <patch> [<doc>]
3	import fs from 'node:fs';
4	import { applyPatch, PatchError } from './jsonpatch.mjs';
5	
6	const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
7	const MAX_BYTES = 1048576;
8	const MAX_DEPTH = 1000;
9	const CHUNK = 65536;
10	
11	class CliError extends Error {
12	  constructor(message, code) {
13	    super(message);
14	    this.code = code;
15	  }
16	}
17	
18	function sleep(ms) {
19	  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
20	}
21	
22	// Reads at most MAX_BYTES + 1 bytes from fd; returns a Buffer or throws an fs error.
23	function readFd(fd) {
24	  const chunks = [];
25	  let total = 0;
26	  for (;;) {
27	    const buf = Buffer.alloc(CHUNK);
28	    let n;
29	    try {
30	      n = fs.readSync(fd, buf, 0, CHUNK, null);
31	    } catch (err) {
32	      if (err.code === 'EAGAIN') {
33	        sleep(10);
34	        continue;
35	      }
36	      throw err;
37	    }
38	    if (n === 0) break;
39	    chunks.push(buf.subarray(0, n));
40	    total += n;
41	    if (total > MAX_BYTES) break;
42	  }
43	  return Buffer.concat(chunks, total);
44	}
45	
46	function readError(name, reason) {
47	  return new CliError(`Error: ${name}: ${reason}`, 1);
48	}
49	
50	function isDirectory(path) {
51	  try {
52	    return fs.statSync(path).isDirectory();
53	  } catch {
54	    return false;
55	  }
56	}
57	
58	function readInput(arg) {
59	  if (arg === '-') {
60	    try {
61	      return readFd(0);
62	    } catch {
63	      throw readError('stdin', 'cannot read');
64	    }
65	  }
66	  let fd;
67	  try {
68	    fd = fs.openSync(arg, 'r');
69	  } catch (err) {
70	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw readError(arg, 'no such file');
71	    throw readError(arg, err.code === 'EISDIR' || isDirectory(arg) ? 'is a directory' : 'cannot read');
72	  }
73	  try {
74	    if (fs.fstatSync(fd).isDirectory()) throw readError(arg, 'is a directory');
75	    return readFd(fd);
76	  } catch (err) {
77	    if (err instanceof CliError) throw err;
78	    throw readError(arg, err.code === 'EISDIR' ? 'is a directory' : 'cannot read');
79	  } finally {
80	    fs.closeSync(fd);
81	  }
82	}
83	
84	// Depth of a parsed JSON value, computed without recursion.
85	function depthOf(value) {
86	  let max = 0;
87	  const stack = [[value, 0]];
88	  while (stack.length) {
89	    const [v, d] = stack.pop();
90	    if (v === null || typeof v !== 'object') continue;
91	    const depth = d + 1;
92	    if (depth > max) max = depth;
93	    for (const child of Array.isArray(v) ? v : Object.values(v)) stack.push([child, depth]);
94	  }
95	  return max;
96	}
97	
98	function loadJson(arg) {
99	  const name = arg === '-' ? 'stdin' : arg;
100	  const bytes = readInput(arg);
101	  if (bytes.length > MAX_BYTES) throw readError(name, 'too large');
102	  let text;
103	  try {
104	    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
105	  } catch {
106	    throw new CliError(`Error: ${name}: invalid UTF-8`, 3);
107	  }
108	  let value;
109	  try {
110	    value = JSON.parse(text);
111	  } catch {
112	    throw new CliError(`Error: ${name}: invalid JSON`, 3);
113	  }
114	  if (depthOf(value) > MAX_DEPTH) throw new CliError(`Error: ${name}: too deep`, 3);
115	  return value;
116	}
117	
118	function run(args) {
119	  if (args.length < 1 || args.length > 2) throw new CliError(USAGE, 2);
120	  const [patchArg, docArg = '-'] = args;
121	  if (patchArg === '-' && docArg === '-') throw new CliError(USAGE, 2);
122	  const patch = loadJson(patchArg);
123	  const doc = loadJson(docArg);
124	  try {
125	    return applyPatch(doc, patch);
126	  } catch (err) {
127	    if (err instanceof PatchError) throw new CliError(`Error: ${err.message}`, 4);
128	    throw err;
129	  }
130	}
131	
132	try {
133	  const result = run(process.argv.slice(2));
134	  process.stdout.write(JSON.stringify(result, null, 2) + '\n');
135	  process.exitCode = 0;
136	} catch (err) {
137	  if (!(err instanceof CliError)) throw err;
138	  process.stderr.write(err.message + '\n');
139	  process.exitCode = err.code;
140	}
